Object.assign(hc,{venueType:'all',pairType:'perp-perp',units:'pct',costs:true,limit:50,minFunding:'',minSpread:'',minVsAvg:'',minVolume:'',minOi:'',minLeverage:'',minNet:'',sameInterval:false,paidPositive:false,oneAsset:false,columns:['spread','average','fees','net','trend','risk'],readJobs:{},presets:[]});
try{hc.presets=JSON.parse(localStorage.getItem('neutralbasis.presets')||'[]')}catch{}
const wideKinds=()=>Object.fromEntries((viewData().registry||[]).map(r=>[r.id,r.kind]));
const wpct=x=>x==null?'—':hc.units==='bp'?(x*10000).toFixed(3)+' bp':pct(x);
const wrate=x=>x==null?'—':hc.units==='bp'?(x*hc.period*10000).toFixed(3)+' bp':rate(x);
const intervalLabel=x=>x==null?'?':x===0?'spot':(x/3600)+'h';
const keyFor=p=>[p.asset,p.long,p.short,p.pair_type||'perp-perp'].join(':');
const wideFilterFields=['query','venue','venueType','pairType','units','costs','period','size','minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet','sameInterval','paidPositive','oneAsset','sort'];
function savePreset(){const input=document.getElementById('preset-name'),title=input.value.trim();if(!title)return;const data=Object.fromEntries(wideFilterFields.map(k=>[k,hc[k]]));hc.presets=[...hc.presets.filter(p=>p.name!==title),{name:title,tab,data}].slice(-6);localStorage.setItem('neutralbasis.presets',JSON.stringify(hc.presets));notice='Filtre kaydedildi.';render()}
function applyPreset(i){const p=hc.presets[i];Object.assign(hc,p.data);navigate(p.tab)}
function resetFilters(){for(const k of ['minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet','query'])hc[k]='';Object.assign(hc,{venue:'all',venueType:'all',sameInterval:false,paidPositive:false,oneAsset:false,favorites:false,positive:false,above:false,limit:50});document.getElementById('global-search').value='';render()}
async function shareFilters(){const params=new URLSearchParams();for(const k of wideFilterFields)params.set(k,String(hc[k]));const link=location.origin+location.pathname+'#'+tab+'?'+params;try{await navigator.clipboard.writeText(link);notice='Filtre bağlantısı panoya kopyalandı.'}catch{notice=link}render()}
function wideParseLink(){const params=new URLSearchParams(location.hash.split('?')[1]||'');if(!params.size)return;for(const k of wideFilterFields)if(params.has(k)){const val=params.get(k);hc[k]=typeof hc[k]==='boolean'?val==='true':typeof hc[k]==='number'?Number(val):val}tab=location.hash.slice(1).split('?')[0]||'funding'}
wideParseLink();window.addEventListener('hashchange',wideParseLink);
const btLinkParams=new URLSearchParams(location.hash.split('?')[1]||'');if(btLinkParams.has('asset')){for(const k of ['long_kind','start_iso','end_iso'])if(btLinkParams.has(k))hc.btForm[k]=btLinkParams.get(k);if([1,7,30,90].includes(Number(btLinkParams.get('days'))))hc.days=Number(btLinkParams.get('days'));if(btLinkParams.has('slippage_bps'))hc.btForm.slippage_bps=Number(btLinkParams.get('slippage_bps'));if(btLinkParams.has('price'))hc.btForm.include_price=btLinkParams.get('price')==='true'}
async function shareBacktest(){const p=new URLSearchParams();for(const k of ['asset','long','short','size','long_kind','slippage_bps','start_iso','end_iso'])if(hc.btForm[k]!=null)p.set(k,String(hc.btForm[k]));p.set('days',hc.days);p.set('price',hc.btForm.include_price);const link=location.origin+location.pathname+'#backtest?'+p;try{await navigator.clipboard.writeText(link);notice='Backtest kurulum bağlantısı kopyalandı.'}catch{notice=link}render()}
const originalWideBacktest=backtestScreen;backtestScreen=function(){return originalWideBacktest().replace('<h2>Sonuç</h2>','<h2>Sonuç</h2><button onclick="shareBacktest()">Kurulum bağlantısı ↗</button>')};
function advancedFilters(){const fields=[['minFunding','Asgari funding · '+periodLabel()+(hc.units==='bp'?' / bp':' / %')],['minSpread','Asgari fiyat farkı · bp'],['minVsAvg','7g ortalamasından uzaklık · bp'],['minVolume','Her bacak 24s hacim · USD'],['minOi','Her perp bacak OI · USD'],['minLeverage','Her bacak azami kaldıraç ≥'],['minNet','Ücret sonrası gösterge ≥ USD']];return `<div class="wide-filter-panel ${hc.help?'open':''}"><form id="wide-filters"><div class="filter-grid">${fields.map(([k,label])=>`<label>${label}<input type="number" name="${k}" value="${esc(hc[k])}" step="any" placeholder="Sınır yok"></label>`).join('')}</div><div class="filters"><label><input type="checkbox" name="sameInterval" ${hc.sameInterval?'checked':''}> Aynı ödeme aralığı</label><label><input type="checkbox" name="paidPositive" ${hc.paidPositive?'checked':''}> Gerçekleşmiş 7g funding pozitif</label><label><input type="checkbox" name="oneAsset" ${hc.oneAsset?'checked':''}> Varlık başına bir çift</label><button class="primary">Filtreleri uygula</button><button type="button" onclick="resetFilters()">Sıfırla</button></div><p class="tooltip">Bilinmeyen hacim/OI/geçmiş, bu alanlarda sınır seçildiğinde filtreyi geçmez. Hacim ve OI yalnızca kaynakta USD değeri doğrulanmışsa gösterilir.</p></form></div>`}
commonFilters=function(price=false){const cov=viewData().coverage||{};return `<div class="toolbar"><div class="toolbar-left"><button onclick="hcSet('help',!hc.help)">☷ Filtreler ${hc.help?'▴':'▾'}</button><span class="screener-count">${cov.available||0} erişilebilir / ${cov.total||63} platform</span><div class="segmented">${['all','DEX','CEX'].map(k=>`<button class="${hc.venueType===k?'active':''}" onclick="hcSet('venueType','${k}')">${k==='all'?'Tümü':k}</button>`).join('')}</div><button onclick="hcSet('favorites',!hc.favorites)" class="${hc.favorites?'active':''}">★ Favoriler</button></div><div class="rate-control">${periods()}<div class="segmented"><button class="${hc.units==='pct'?'active':''}" onclick="hcSet('units','pct')">%</button><button class="${hc.units==='bp'?'active':''}" onclick="hcSet('units','bp')">bp</button></div><select aria-label="Borsa filtresi" onchange="hcSet('venue',this.value)"><option value="all">Tüm borsalar</option>${hcVenues.map(v=>`<option value="${v}" ${hc.venue===v?'selected':''}>${esc(name(v))}</option>`).join('')}</select></div></div>${advancedFilters()}<div class="filters"><div class="segmented"><button class="${hc.pairType==='perp-perp'?'active':''}" onclick="hcSet('pairType','perp-perp')">Perp + perp</button>${price?`<button class="${hc.pairType==='spot-perp'?'active':''}" onclick="hcSet('pairType','spot-perp')">Spot + perp</button><button class="${hc.pairType==='all'?'active':''}" onclick="hcSet('pairType','all')">İkisi</button>`:''}</div><label class="tooltip"><input type="checkbox" ${hc.costs?'checked':''} onchange="hcSet('costs',this.checked)"> Göstergeye taker ücretlerini dahil et</label><button onclick="shareFilters()">Bağlantıyı kopyala ↗</button><input id="preset-name" aria-label="Filtre kaydı adı" placeholder="Filtre kaydı adı" maxlength="40"><button onclick="savePreset()">Filtreyi kaydet</button>${hc.presets.map((p,i)=>`<button onclick="applyPreset(${i})">${esc(p.name)}</button>`).join('')}</div>`};
netEstimate=function(p,price){if((hc.costs&&p.fee_roundtrip==null)||(price&&!p.history)||(!price&&p.funding==null))return null;return hc.size*((price?p.spread-p.history.mean:p.funding*state.config.horizon)-(hc.costs?p.fee_roundtrip:0))};
filteredPairs=function(price){const kinds=wideKinds();let ps=viewData().pairs.filter(p=>price?hc.pairType==='all'||p.pair_type===hc.pairType:p.pair_type==='perp-perp').map(p=>{if(price||p.funding==null||p.funding>=0)return {...p};return {...p,long:p.short,short:p.long,long_price:p.short_price,short_price:p.long_price,funding:-p.funding,spread:-p.spread,paid24:p.paid24==null?null:-p.paid24,paid7:p.paid7==null?null:-p.paid7,long_interval:p.short_interval,short_interval:p.long_interval,history:p.history?{...p.history,mean:-p.history.mean,points:p.history.points.map(x=>({...x,spread:-x.spread,long_price:x.short_price,short_price:x.long_price}))}:null}});
 ps=ps.filter(p=>(!hc.query||[p.asset,p.long,p.short,name(p.long),name(p.short)].join(' ').toLowerCase().includes(hc.query.toLowerCase()))&&(hc.venue==='all'||[p.long,p.short].includes(hc.venue))&&(hc.venueType==='all'||[p.long,p.short].every(v=>kinds[v]===hc.venueType))&&(!hc.favorites||hc.stars.has(keyFor(p)))&&(!hc.above||p.history&&p.spread>p.history.mean)&&(!hc.sameInterval||p.long_interval===p.short_interval)&&(!hc.paidPositive||p.paid7>0));
 const threshold=(key,value)=>hc[key]===''||value!=null&&Number.isFinite(value)&&value>=Number(hc[key]);
 ps=ps.filter(p=>threshold('minFunding',p.funding==null?null:p.funding*hc.period*(hc.units==='bp'?10000:100))&&threshold('minSpread',p.spread*10000)&&threshold('minVsAvg',p.history?(p.spread-p.history.mean)*10000:null)&&threshold('minVolume',p.min_volume)&&threshold('minOi',p.min_oi)&&threshold('minLeverage',p.leverage)&&threshold('minNet',netEstimate(p,price)));
 ps.sort((a,b)=>hc.sort==='asset'?a.asset.localeCompare(b.asset):hc.sort==='net'?(netEstimate(b,price)??-Infinity)-(netEstimate(a,price)??-Infinity):hc.sort==='volume'?(b.min_volume??-Infinity)-(a.min_volume??-Infinity):hc.sort==='paid7'?(b.paid7??-Infinity)-(a.paid7??-Infinity):price?b.spread-a.spread:(b.funding??-Infinity)-(a.funding??-Infinity));
 if(hc.oneAsset){const seen=new Set();ps=ps.filter(p=>{if(seen.has(p.asset))return false;seen.add(p.asset);return true})}hc.total=ps.length;return ps.slice(0,hc.limit)};
function wideStar(key){hc.stars.has(key)?hc.stars.delete(key):hc.stars.add(key);localStorage.setItem('neutralbasis.favorites',JSON.stringify([...hc.stars]));render()}
function columnToggle(id){hc.columns=hc.columns.includes(id)?hc.columns.filter(c=>c!==id):[...hc.columns,id];render()}
function wideColumns(){return `<details class="columns-control"><summary>Sütunlar ${hc.columns.length}/10</summary><div>${[['spread','Fiyat farkı'],['average','7g ortalaması'],['fees','4 emir ücretleri'],['net','Net gösterge'],['trend','Spread grafiği'],['risk','Risk durumu'],['liquidity','Hacim / OI'],['leverage','Kaldıraç'],['paid','Gerçekleşmiş funding'],['interval','Ödeme aralığı']].map(([k,l])=>`<label><input type="checkbox" ${hc.columns.includes(k)?'checked':''} onchange="columnToggle('${k}')"> ${l}</label>`).join('')}</div></details>`}
screener=function(price=false){const ps=filteredPairs(price),col=k=>hc.columns.includes(k),cov=viewData().coverage||{};return head(price?'Fiyat arbitrajı':'Funding oranları',`${cov.dex||0} DEX + ${cov.cex||0} CEX erişilebilir. ${state.config.symbols.length} seçili varlık; public piyasa verileri, bağımsız paper risk motoru.`)+`<div class="filters"><div class="segmented"><button class="${hc.view==='list'?'active':''}" onclick="hcSet('view','list')">Çift listesi</button>${!price?`<button class="${hc.view==='matrix'?'active':''}" onclick="hcSet('view','matrix')">Borsa matrisi</button>`:''}<button class="${hc.view==='venues'?'active':''}" onclick="hcSet('view','venues')">İki borsa</button></div><span class="tooltip">${cov.adapters||0} public adaptör / ${cov.total||63} katalog kaydı. <a href="#exchanges">Kapsam ve eksikler ↗</a></span></div>`+(hc.view==='venues'?venuePairs(price):commonFilters(price)+(!price&&hc.view==='matrix'?fundingMatrix():`<div class="toolbar"><span class="screener-count">${hc.total.toLocaleString()} çift · ilk ${ps.length}</span><div class="rate-control"><input id="pair-search" class="search" aria-label="Çift tablosunda ara" placeholder="Varlık veya borsa ara" value="${esc(hc.query)}" oninput="hcQuery(this)"><label class="inline-label">Bacak / USD<input aria-label="Gösterge bacak büyüklüğü" type="number" min="10" max="1000000" value="${hc.size}" oninput="hc.size=Number(this.value)||1000" onchange="render()"></label><select aria-label="Sıralama" onchange="hcSet('sort',this.value)">${[['funding',price?'Fiyat farkı ↓':'Funding farkı ↓'],['net','Net gösterge ↓'],['volume','24s hacim ↓'],['paid7','Gerçekleşmiş funding 7g ↓'],['asset','Varlık A–Z']].map(([v,l])=>`<option value="${v}" ${hc.sort===v?'selected':''}>${l}</option>`).join('')}</select>${wideColumns()}</div></div><div class="table-wrap"><table aria-label="${price?'Fiyat arbitrajı':'Funding çiftleri'}"><thead><tr><th></th><th>VARLIK</th><th>LONG / SHORT</th><th class="num">FUNDING / ${periodLabel()}</th>${col('spread')?'<th class="num">FİYAT FARKI</th>':''}${col('average')?'<th class="num">7G ORT. FARKI</th>':''}${col('fees')?'<th class="num">ÜCRET · 4 EMİR</th>':''}${col('net')?'<th class="num">NET GÖSTERGE¹</th>':''}${col('liquidity')?'<th class="num">HACİM / OI · USD</th>':''}${col('leverage')?'<th class="num">KALDIRAÇ</th>':''}${col('paid')?'<th class="num">ÖDENEN · 24S / 7G</th>':''}${col('interval')?'<th>ÖDEME ARALIĞI</th>':''}${col('trend')?'<th>SPREAD · 7G</th>':''}${col('risk')?'<th>PAPER DURUMU</th>':''}<th></th></tr></thead><tbody>${ps.map(p=>{const key=keyFor(p),net=netEstimate(p,price),avg=p.history?p.spread-p.history.mean:null;const deep=state.candidates.find(c=>c.asset===p.asset&&c.long===p.long&&c.short===p.short);return `<tr class="${hc.expanded===key?'selected':''}" tabindex="0" onclick="hcSet('expanded',hc.expanded==='${key}'?null:'${key}')" onkeydown="if(event.key==='Enter')hcSet('expanded','${key}')"><td><button class="fav ${hc.stars.has(key)?'on':''}" aria-label="${esc(p.asset+' '+name(p.long)+' '+name(p.short))} favori" onclick="event.stopPropagation();wideStar('${key}')">${hc.stars.has(key)?'★':'☆'}</button></td><td>${assetCell(p.asset).replace('PERP / PERP',p.pair_type==='spot-perp'?'SPOT / PERP':'PERP / PERP')}<div class="cell-sub">${p.pair_type==='spot-perp'?'SPOT → PERP':'PERP → PERP'}</div></td><td>${venueLeg(p.long,'L',p.long_price)}${venueLeg(p.short,'S',p.short_price)}<div class="cell-sub">${esc(p.long_price_type||'mark')} / ${esc(p.short_price_type||'mark')}</div></td><td class="num mono ${color(p.funding)}">${wrate(p.funding)}</td>${col('spread')?`<td class="num mono ${color(p.spread)}">${wpct(p.spread)}</td>`:''}${col('average')?`<td class="num mono ${color(avg)}">${wpct(avg)}</td>`:''}${col('fees')?`<td class="num mono">${p.fee_roundtrip==null?'—':money(hc.size*p.fee_roundtrip)}<div class="cell-sub">kayma hariç</div></td>`:''}${col('net')?`<td class="num mono ${color(net)}">${signedMoney(net)}<div class="cell-sub">${price?'7g ortalamaya dönüş':state.config.horizon+'s · sabit oran'}${hc.costs?'':' · ücret hariç'}</div></td>`:''}${col('liquidity')?`<td class="num mono">${money(p.min_volume)}<div class="cell-sub">OI ${money(p.min_oi)}</div></td>`:''}${col('leverage')?`<td class="num mono">${p.leverage?p.leverage+'x':'—'}</td>`:''}${col('paid')?`<td class="num mono">${wpct(p.paid24)}<div class="cell-sub">${wpct(p.paid7)}</div></td>`:''}${col('interval')?`<td class="mono">${intervalLabel(p.long_interval)} / ${intervalLabel(p.short_interval)}</td>`:''}${col('trend')?`<td>${spark(p.history?.points)}</td>`:''}${col('risk')?`<td><span class="tag ${deep?.eligible?'':'warn'}">${deep?(deep.eligible?'Funding adayı':'Bekle'):'Veri taraması'}</span></td>`:''}<td>▾</td></tr>${hc.expanded===key?wideDrawer(p):''}`}).join('')}</tbody></table>${ps.length?'':'<div class="empty"><h2>Bu koşullarda doğrulanmış çift yok</h2><p>Bağlantı kapsamını ve eksik veri durumlarını Borsalar ekranından görebilirsin.</p><button onclick="resetFilters()">Filtreleri temizle</button></div>'}</div><div class="toolbar"><span class="tooltip">¹ Gösterge hesabı. Gelecek funding, kayma, likidasyon ve stres kesin getirisi değildir. USD/USDT/USDC/USDG 1:1 varsayılır.</span>${hc.total>hc.limit?'<button onclick="hc.limit+=100;render()">100 çift daha göster ↓</button>':''}</div>`))};
// Two venues side by side: every asset both list, its funding carry (long the lower rate) and
// its price gap (long the cheaper), with four taker fees, a 24h estimate at the current rates
// and the last 7 days realized (funding paid + both legs' price change, from stored history).
function venuePairs(price){loadMatrix();const d=mxData;if(!d)return `<div class="plot-empty">${mxError?esc(mxError):'Funding matrisi yükleniyor…'}</div>`;
 const ids=d.venues.map(v=>v.id).sort((x,y)=>name(x).localeCompare(name(y))),pick=(k,pref,not)=>{if(!ids.includes(hc[k])||hc[k]===not)hc[k]=pref.find(v=>ids.includes(v)&&v!==not)||ids.find(v=>v!==not)};
 pick('vpA',['Hyperliquid'],null);pick('vpB',['Binance','Bybit'],hc.vpA);
 const A=hc.vpA,B=hc.vpB,size=hc.size,floor=hc.vpLiq??1e6,sort=hc.vpSort||(price?'price':'net24'),rows=[];let other=0,thin=0;
 for(const x of d.assets){const a=x.cells[A],b=x.cells[B];if(!a||!b)continue;if(!samePrice(a,b)){other++;continue}if(!legLiquid(d,A,a,floor)||!legLiquid(d,B,b,floor)){thin++;continue}
  const [Lc,Sc,lv,sv]=a[0]<=b[0]?[a,b,A,B]:[b,a,B,A],gap=Sc[0]-Lc[0],fee=a[2]!=null&&b[2]!=null?2*(a[2]+b[2]):null,cost=!hc.costs?0:fee==null?null:fee*size,fund24=gap*24*size,
   px=a[4]&&b[4]?Math.log(b[4]/a[4]):null,px7=a[7]&&b[7]?Math.log(b[7]/a[7]):null,n7=pairNet7(Lc,Sc),depth=c=>c[6]??c[5];
  rows.push({asset:x.asset,lv,sv,gap,fund24,cost,net24:cost==null?null:fund24-cost,net7:n7.net,n7,px,px7,cheap:!px?null:px>0?A:B,dear:!px?null:px>0?B:A,pxNet:px==null||cost==null?null:Math.abs(px)*size-cost,depth:Math.min(depth(a)??Infinity,depth(b)??Infinity)})}
 const key={net24:x=>x.net24,gap:x=>x.gap,net7:x=>x.net7,price:x=>x.px==null?null:Math.abs(x.px),asset:null}[sort];
 rows.sort(key?(x,y)=>(key(y)??-Infinity)-(key(x)??-Infinity):(x,y)=>x.asset.localeCompare(y.asset));
 const sel=(k,v)=>`<select aria-label="${k==='vpA'?'Borsa A':'Borsa B'}" onchange="hcSet('${k}',this.value)">${ids.map(id=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(name(id))}</option>`).join('')}</select>`;
 const shown=rows.slice(0,hc.vpLimit||100),pos24=rows.filter(x=>x.net24>0).length,pos7=rows.filter(x=>x.net7>0).length,posPx=rows.filter(x=>x.pxNet>0).length,pp=x=>x==null?'—':(x>0?'+':'')+(x*100).toFixed(3)+'%';
 const head=`<div class="toolbar"><div class="toolbar-left"><label class="inline-label">A ${sel('vpA',A)}</label><button aria-label="Borsaları değiştir" onclick="const t=hc.vpA;hc.vpA=hc.vpB;hc.vpB=t;render()">⇄</button><label class="inline-label">B ${sel('vpB',B)}</label></div><div class="rate-control">${periods()}<select aria-label="Likidite" onchange="hcSet('vpLiq',Number(this.value))">${[[0,'Tüm likidite'],[1e6,'Her bacak ≥ $1M'],[1e7,'Her bacak ≥ $10M']].map(([v,l])=>`<option value="${v}" ${floor===v?'selected':''}>${l}</option>`).join('')}</select><select aria-label="Sıralama" onchange="hcSet('vpSort',this.value)">${[['net24','24s funding net ↓'],['net7','Son 7g gerçekleşen ↓'],['gap','Funding farkı ↓'],['price','Fiyat farkı ↓'],['asset','Varlık A–Z']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select><label class="inline-label">Bacak / USD<input type="number" min="10" max="1000000" value="${size}" onchange="hc.size=Number(this.value)||1000;render()"></label><label class="tooltip"><input type="checkbox" ${hc.costs?'checked':''} onchange="hcSet('costs',this.checked)"> 4 taker ücretini düş</label></div></div>
 <p class="tooltip">${esc(name(A))} ve ${esc(name(B))}: ${rows.length} ortak likit varlık · 24 saatte funding neti pozitif ${pos24} · son 7 günde gerçekleşen neti pozitif ${pos7} · fiyat farkı ücretleri aşan ${posPx}${other?` · ${other} varlık farklı token gibi görünüyor (fiyatlar %15'ten fazla ayrışıyor), gösterilmedi`:''}${thin?` · ${thin} varlık likidite sınırı altında`:''}.</p>`;
 const body=shown.map(x=>`<tr tabindex="0" onclick="location.hash='#pair?'+new URLSearchParams({asset:'${esc(x.asset)}',long:'${esc(x.lv)}',short:'${esc(x.sv)}'})"><td><b>${esc(x.asset)}</b></td><td><span class="good">LONG</span> ${esc(name(x.lv))}<div class="cell-sub"><span class="bad">SHORT</span> ${esc(name(x.sv))}</div></td><td class="num mono good">${rate(x.gap)}<div class="cell-sub">APR ${(x.gap*8760*100).toFixed(1)}%</div></td><td class="num mono ${color(x.fund24)}">${signedMoney(x.fund24)}</td><td class="num mono">${x.cost==null?'—':money(x.cost)}</td><td class="num mono ${color(x.net24)}"><b>${signedMoney(x.net24)}</b></td><td class="num mono ${color(x.net7)}">${x.net7==null?'<span class="muted">geçmiş eksik</span>':signedMoney(x.net7)}${flipNote(x.n7,x.gap,x.lv,x.sv)}</td><td class="num mono">${pp(x.px)}<div class="cell-sub">${x.cheap?`ucuz ${esc(name(x.cheap))} · 7g önce ${pp(x.px7)}`:''}</div></td><td class="num mono ${color(x.pxNet)}">${signedMoney(x.pxNet)}</td><td class="num mono">${x.depth===Infinity?'—':money(x.depth)}</td><td>→</td></tr>`).join('')||`<tr><td colspan="11" class="muted">Bu iki borsada ortak likit varlık yok.</td></tr>`;
 return head+`<div class="table-wrap"><table aria-label="İki borsa fırsatları"><thead><tr><th>VARLIK</th><th>FUNDING YÖNÜ</th><th class="num">FUNDING FARKI / ${periodLabel()}</th><th class="num">24S FUNDING</th><th class="num">4 ÜCRET</th><th class="num">24S NET¹</th><th class="num">SON 7G GERÇEKLEŞEN²</th><th class="num">FİYAT FARKI (B/A − 1)</th><th class="num">FARK KAPANIRSA³</th><th class="num">EN İNCE BACAK · OI/HACİM</th><th></th></tr></thead><tbody>${body}</tbody></table></div><div class="toolbar"><span class="tooltip">¹ Anlık oranlarla 24 saat funding − 4 taker ücreti; oranlar değişir. ² Çift 7 gün önce açılıp şimdi kapansaydı: gerçekleşen funding + iki bacağın fiyat değişimi − ücret; geçmiş kayıtlı değilse gösterilmez. ³ Fiyat farkının tamamı kapanırsa ucuzda long, pahalıda short kazancı − ücret; normal fark sıfır olmayabilir, gösterge değildir. Satıra tıklayınca çift sayfası açılır.</span>${rows.length>shown.length?`<button onclick="hc.vpLimit=(hc.vpLimit||100)+100;render()">100 varlık daha göster ↓</button>`:''}</div>`}
function wideDrawer(p){const key=keyFor(p),q=hc.readJobs.quote,h=hc.readJobs.history,qr=q?.status==='done'&&q.result.asset===p.asset&&q.result.long===p.long&&q.result.short===p.short?q.result:null;return `<tr><td colspan="20" style="padding:0;white-space:normal"><div class="drawer"><div class="drawer-grid"><div><h2>${esc(p.asset)} · ${esc(name(p.long))} / ${esc(name(p.short))}</h2><p class="tooltip">${p.pair_type==='spot-perp'?'Spot long, perpetual short. Spot short/borç varsayılmaz.':'İki perpetual bacağı.'} Fiyat kaynakları: ${esc(p.long_price_type)} / ${esc(p.short_price_type)}.</p>${pairPriceCharts(p)}<button onclick="requestRead('history','${p.asset}','${p.long}','${p.short}','${p.long_kind}')" ${h?.status==='running'?'disabled':''}>${h?.status==='running'?'Geçmiş hazırlanıyor…':'7 günlük geçmişi ve funding’i getir'}</button><p class="tooltip">Geçmiş eksikse ileri doldurma yapılmaz. Oracle serileri perp uyum onayı almaz.</p></div><div>${line('Anlık fiyat farkı',wpct(p.spread))}${line('7 günlük ortalama',wpct(p.history?.mean))}${line('Sıfır çevresinde kesişim · 7g',p.history?.crossings??'Geçmişi getir')}${line('Gerçekleşmiş funding · 24s / 7g',wpct(p.paid24)+' / '+wpct(p.paid7))}${line('Ödeme aralıkları',intervalLabel(p.long_interval)+' / '+intervalLabel(p.short_interval))}${line('Bacak başına gösterge büyüklüğü',money(hc.size))}<p class="tooltip">${esc(p.reason||'Bu borsa çifti için otomatik paper yürütme henüz onaylı değil.')}</p><div class="filters"><button class="primary" onclick="requestRead('quote','${p.asset}','${p.long}','${p.short}','${p.long_kind}')" ${q?.status==='running'?'disabled':''}>${q?.status==='running'?'Defterler okunuyor…':'Dört emri defterle hesapla'}</button><button onclick="openWideBacktest('${p.asset}','${p.long}','${p.short}','${p.long_kind}')">Backtest ↗</button></div>${qr?`${line('Defterden giriş fiyat avantajı',money(qr.entry_capture))}${line('Dört emrin taker ücreti',money(qr.fees))}${line('Çıkış kayması vekili',money(qr.exit_drag_proxy))}${line('Sıfıra yakınsama net modeli',signedMoney(qr.convergence_net_model),color(qr.convergence_net_model))}<p class="tooltip">${esc(qr.method)}<br>${ts(qr.received)} · kayıtlar ${qr.audit_ids.join(', ')}</p>`:''}${[q,h].filter(j=>j?.status==='error').map(j=>`<div class="reason bad">${esc(j.error)}</div>`).join('')}</div></div></div></td></tr>`}
async function requestRead(kind,asset,long,short,long_kind){try{hc.readJobs[kind]={status:'running'};render();const resp=await fetch('/api/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-Paper-Token':window.paperToken},body:JSON.stringify({asset,long,short,long_kind,size:hc.size})});const r=await resp.json();if(!resp.ok)throw Error(r.error);pollReads(kind)}catch(e){hc.readJobs[kind]={status:'error',error:e.message};render()}}
async function pollReads(kind){try{const resp=await fetch('/api/read-jobs');if(!resp.ok)throw Error('Analiz bağlantısı yok');const jobs=await resp.json();hc.readJobs=jobs;if(jobs[kind]?.status==='running'){setTimeout(()=>pollReads(kind),1500);return}await refresh();render()}catch(e){hc.readJobs[kind]={status:'error',error:e.message};render()}}
function openWideBacktest(a,l,s,k){hc.btForm.long_kind=k;openBacktest(a,l,s)}
exchangeScreen=function(){const reg=viewData().registry||[],cov=viewData().coverage||{};return head('Borsalar ve bağlantı kapsamı','Tüm referans platformları burada listelenir. Katalog kaydı, çalışan public veri adaptörü ve paper yürütme ayrı durumlardır.')+`<div class="stat-grid">${[['Katalog',cov.total||63,'DEX + CEX'],['Public adaptör',cov.adapters||0,'Doğrulanan kod bağlantıları'],['Şu an erişilebilir',cov.available||0,(cov.cex||0)+' CEX · '+(cov.dex||0)+' DEX'],['Paper yürütme',state.wide_paper?state.wide_paper.venues.length:2,state.wide_paper?'Çoklu paper: veri gelen tüm borsalar · eski masa yalnızca Lighter RH–Extended':'Lighter RH ve Extended']].map(([l,n,t])=>`<div class="metric"><div class="label">${l}</div><div class="number">${n}</div><small>${t}</small></div>`).join('')}</div><div class="reason">Her platform bağlı değil. “Adaptör eksik” kayıtları fiyat tablosuna ve paper işlem havuzuna alınmaz. Erişim hatası, bölgesel engel ve eksik API alanları ayrıca gösterilir.</div><div class="table-wrap"><table aria-label="Borsa kapsamı"><thead><tr><th>BORSA</th><th>TÜR</th><th>PUBLIC VERİ</th><th>PAPER</th><th>AÇIKLAMA</th><th></th></tr></thead><tbody>${reg.map(r=>`<tr><td><b>${esc(r.label)}</b></td><td>${r.kind}</td><td><span class="tag ${r.fresh?'':'warn'}">${r.fresh?'Erişilebilir':r.status==='adapter_missing'?'Adaptör eksik':r.status==='unavailable'?'Bağlantı hatası':'Test / tarama bekleniyor'}</span></td><td>${r.paper?'Doğrulanmış model':'İşlem dışı'}</td><td style="white-space:normal;max-width:500px" class="tooltip">${esc(r.message||r.note)}</td><td>${r.fresh?`<button onclick="hc.venue='${r.id}';navigate('funding')">Piyasalar ↗</button>`:''}</td></tr>`).join('')}</tbody></table></div>`};
const baseWideRender=render;render=function(){if(state?.market_view?.registry){hcVenues=state.market_view.registry.map(v=>v.id);const strip=document.querySelector('.strip-left');if(strip){const info=strip.querySelector(':scope > span:nth-child(2)');if(info)info.textContent=state.config.symbols.length+' VARLIK / '+state.market_view.coverage.available+' ERİŞİLEBİLİR BORSA'}}baseWideRender();const form=document.getElementById('wide-filters');form?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);for(const k of ['minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet'])hc[k]=data.get(k);for(const k of ['sameInterval','paidPositive','oneAsset'])hc[k]=data.has(k);hc.limit=50;render()})};
hc.theme=localStorage.getItem('neutralbasis.theme')||'dark';document.documentElement.dataset.theme=hc.theme;
